)

// احتفظ بالمعرّفات الأصلية حتى لا يؤدي توسيع المجموعة إلى حذف عدّادات اليوم.
private fun dailyAdhkar(evening: Boolean): List<Dhikr> {
    val time = if (evening) "أَمْسَيْنَا" else "أَصْبَحْنَا"
    val singular = if (evening) "أَمْسَيْتُ" else "أَصْبَحْتُ"
    val period = if (evening) "اللَّيْلَةِ" else "الْيَوْمِ"
    val after = if (evening) "بَعْدَهَا" else "بَعْدَهُ"
    return listOf(
        fatiha, ayatKursi, baqarahEnding,
        ikhlas, falaq, nas,
        Dhikr("salawat-ten", "الصلاة على النبي ﷺ عشر مرات", "اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَى سَيِّدِنَا مُحَمَّدٍ", 10, "ذكر عام • العدد المقترح 10"),
        Dhikr("kingdom", if (evening) "أمسينا وأمسى الملك لله" else "أصبحنا وأصبح الملك لله",
            "$time وَ${if (evening) "أَمْسَى" else "أَصْبَحَ"} الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. رَبِّ أَسْأَلُكَ خَيْرَ هَذِهِ $period وَخَيْرَ مَا $after، وَأَعُوذُ بِكَ مِنْ شَرِّ هَذِهِ $period وَشَرِّ مَا $after. رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ".let {
                // تتغير صيغة اسم الإشارة العربية بحسب كلمة «اليوم» المذكرة.
                if (evening) it else it.replace("هَذِهِ الْيَوْمِ", "هَذَا الْيَوْمِ")
            }, 1, "صحيح مسلم • 2723"),
        Dhikr(if (evening) "evening" else "morning", if (evening) "دعاء المساء" else "دعاء الصباح",
            if (evening) "اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ"
            else "اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ", 1, "أبو داود • 5068"),
        istighfar,
        Dhikr("witness", "اللهم إني أشهدك", "اللَّهُمَّ إِنِّي $singular أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ", 4, "أبو داود • 5069؛ مختلف في تصحيحه"),
        Dhikr("gratitude", "شكر النعمة", "اللَّهُمَّ مَا ${if (evening) "أَمْسَى" else "أَصْبَحَ"} بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ، فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ", 1, "أبو داود • 5073؛ مختلف في تصحيحه"),
        Dhikr("health", "العافية في البدن والسمع والبصر", "اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَٰهَ إِلَّا أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَٰهَ إِلَّا أَنْتَ", 3, "أبو داود • 5090"),
        Dhikr("reliance", "حسبي الله", "حَسْبِيَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ", 7, "أبو داود • 5081؛ أثر عن أبي الدرداء"),
        Dhikr("wellbeing", "العفو والعافية", "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي", 1, "أبو داود • 5074"),
        Dhikr("unseen", "عالم الغيب والشهادة", "اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ", 1, "الترمذي • 3392"),
        protection,
        Dhikr("contentment", "رضيت بالله ربًا", "رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا", 3, "أحمد • 18967؛ أبو داود • 5072"),
        Dhikr("living", "يا حي يا قيوم", "يَا حَيُّ يَا قَيُّومُ، بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ", 1, "النسائي • السنن الكبرى؛ الحاكم • المستدرك"),
        Dhikr("day-good", "سؤال خير ${if (evening) "الليلة" else "اليوم"}", "$time وَ${if (evening) "أَمْسَى" else "أَصْبَحَ"} الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ $period، ${if (evening) "فَتْحَهَا، وَنَصْرَهَا، وَنُورَهَا، وَبَرَكَتَهَا، وَهُدَاهَا" else "فَتْحَهُ، وَنَصْرَهُ، وَنُورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ"}، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا ${if (evening) "فِيهَا" else "فِيهِ"} وَشَرِّ مَا $after".let { if (evening) it else it.replace("هَذِهِ الْيَوْمِ", "هَذَا الْيَوْمِ") }, 1, "أبو داود • 5084؛ مختلف في تصحيحه"),
        Dhikr("fitrah", "على فطرة الإسلام", "$time عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ", 1, "أحمد • 15360"),
        tasbih,
        Dhikr("tawhid", "ذكر التوحيد", "لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", 1, "أبو داود • 5077")
    ) + listOf(
        Dhikr("refuge", "التعوذ بكلمات الله", "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ", 3, "الترمذي • 3604؛ صحيح مسلم • 2709")
    ) + additionalDailyAdhkar(evening) + if (evening) emptyList() else listOf(
        Dhikr("praise-three", "عدد خلقه ورضا نفسه", "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ", 3, "صحيح مسلم • 2726"),
        Dhikr("knowledge", "بعد صلاة الصبح", "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا", 1, "ابن ماجه • 925؛ يقال بعد صلاة الصبح"),
        Dhikr("tawhid-day", "التوحيد مائة مرة في اليوم", "لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", 100, "صحيح البخاري • 3293؛ صحيح مسلم • 2691؛ ذكر يومي"),
        Dhikr("repent-day", "الاستغفار مائة مرة في اليوم", "أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ", 100, "صحيح مسلم • 2702؛ ذكر يومي")
    )
}

internal val dhikrGroups = listOf(
    DhikrGroup("morning", "أذكار الصباح", "ابدأ يومك بذكر الله", "sun", dailyAdhkar(false)),
    DhikrGroup("evening", "أذكار المساء", "سكينة في نهاية اليوم", "moon", dailyAdhkar(true)),
    DhikrGroup("prayer", "بعد الصلاة", "أذكار ما بعد التسليم", "mosque", listOf(
        Dhikr("forgive", "الاستغفار", "أَسْتَغْفِرُ اللَّهَ", 3, "صحيح مسلم"),
        Dhikr("peace", "اللهم أنت السلام", "اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ", 1, "صحيح مسلم"),
        Dhikr("subhan", "التسبيح", "سُبْحَانَ اللَّهِ", 33, "صحيح مسلم"),
        Dhikr("hamd", "التحميد", "الْحَمْدُ لِلَّهِ", 33, "صحيح مسلم"),
        Dhikr("takbir", "التكبير", "اللَّهُ أَكْبَرُ", 33, "صحيح مسلم"),
        Dhikr("tawhid", "تمام المائة", "لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", 1, "صحيح مسلم"), ayatKursi)),
    DhikrGroup("sleep", "أذكار النوم", "اختم يومك بالطمأنينة", "sleep", listOf(
        Dhikr("sleep", "دعاء النوم", "بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا", 1, "صحيح البخاري"),
        ayatKursi, ikhlas, falaq, nas,
        Dhikr("subhan", "التسبيح قبل النوم", "سُبْحَانَ اللَّهِ", 33, "متفق عليه"),
        Dhikr("hamd", "التحميد قبل النوم", "الْحَمْدُ لِلَّهِ", 33, "متفق عليه"),
        Dhikr("takbir", "التكبير قبل النوم", "اللَّهُ أَكْبَرُ", 34, "متفق عليه"))),
    DhikrGroup("duas", "أدعية مختارة", "من القرآن والسنة", "hands", listOf(
        Dhikr("good", "خيري الدنيا والآخرة", "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", 1, "القرآن الكريم • البقرة: 201"),
        Dhikr("heart", "ثبات القلب", "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ", 1, "القرآن الكريم • آل عمران: 8"),
        Dhikr("parents", "الدعاء للوالدين", "رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ", 1, "القرآن الكريم • إبراهيم: 41"),
        Dhikr("guidance", "الهدى والعفاف", "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى", 1, "صحيح مسلم"),
        Dhikr("dhikr", "حسن العبادة", "اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ", 1, "رواه أبو داود والنسائي"))),
